const now = new Date();
const sourceUrl = $env.AIRINDEX_SOURCE_URL;
const ingestUrl = $env.AIRINDEX_INGEST_URL;
const indexUrl = $env.AIRINDEX_INDEX_URL;
if (!sourceUrl || !ingestUrl) throw new Error('AIRINDEX_SOURCE_URL and AIRINDEX_INGEST_URL must be configured');
return [{ json: { run_id: `n8n-${now.toISOString().replace(/[-:.TZ]/g, '')}`, collected_at: now.toISOString(), source_url: sourceUrl, ingest_url: ingestUrl, index_url: indexUrl || '', freshness_limit_minutes: Number($env.AIRINDEX_FRESHNESS_LIMIT_MINUTES || 180), anomaly_threshold_pct: Number($env.AIRINDEX_ANOMALY_THRESHOLD_PCT || 35), batch_size: Number($env.AIRINDEX_BATCH_SIZE || 100), workflow_version: '0.2.0' } }];

const context = $('Run Config + Audit ID').first().json;
const first = $input.first()?.json;
let rows;
if (Array.isArray(first)) rows = first;
else if (Array.isArray(first?.observations)) rows = first.observations;
else rows = $input.all().map(item => item.json);
if (!rows.length) throw new Error('Source returned zero observations');

const valid = [];
const rejected = [];
const seen = new Set();
const now = new Date(context.collected_at);

for (const [i, row] of rows.entries()) {
  try {
    const route = String(row.route ?? '').trim().toUpperCase();
    const carrier = String(row.carrier_code ?? row.carrier ?? '').trim().toUpperCase();
    const fare = Number(row.total_fare ?? row.totalFare);
    const observed = new Date(row.observed_at ?? row.collected_at ?? context.collected_at);
    const travel = new Date(row.travel_date);
    const currency = String(row.currency ?? 'INR').toUpperCase();
    const advance = Math.round((travel - observed) / 86400000);
    const key = `${route}|${carrier}|${travel.toISOString().slice(0,10)}|${Math.round(fare * 100)}`;
    if (!/^[A-Z]{3}-[A-Z]{3}$/.test(route)) throw new Error('invalid route');
    if (!/^[A-Z0-9]{2,3}$/.test(carrier)) throw new Error('invalid carrier_code');
    if (!(fare > 0) || fare > 1000000) throw new Error('invalid total_fare');
    if (currency !== 'INR') throw new Error('currency must be INR');
    if (Number.isNaN(observed.getTime()) || Number.isNaN(travel.getTime())) throw new Error('invalid date');
    if (advance < 1 || advance > 365) throw new Error('advance_days outside 1..365');
    if (travel < observed) throw new Error('travel_date before observed_at');
    if (seen.has(key)) throw new Error('duplicate observation in source batch');
    seen.add(key);

    const leadWindows = [1, 7, 15, 30, 45];
    const leadWindow = leadWindows.find(w => advance <= w) ?? 45;
    const ageMinutes = (now - observed) / 60000;
    const freshnessScore = Math.max(0, Math.min(1, 1 - ageMinutes / context.freshness_limit_minutes));
    valid.push({
      route, carrier_code: carrier, observed_at: observed.toISOString(), travel_date: travel.toISOString().slice(0, 10),
      total_fare: Math.round(fare * 100) / 100, advance_days: advance, lead_time_window: `T+${leadWindow}`, currency,
      source: row.source ?? 'configured_source', run_id: context.run_id, freshness_score: Number(freshnessScore.toFixed(4)),
      row_number: i + 1
    });
  } catch (error) {
    rejected.push({ row_number: i + 1, reason: error.message ?? String(error) });
  }
}

if (!valid.length) throw new Error(`All observations rejected: ${JSON.stringify(rejected.slice(0, 5))}`);
return [{ json: { ...context, observations: valid, rejected_count: rejected.length, rejected_examples: rejected.slice(0, 10), source_count: rows.length } }];

const data = $input.first().json;
const observations = data.observations;
const byRoute = new Map();
for (const obs of observations) {
  if (!byRoute.has(obs.route)) byRoute.set(obs.route, []);
  byRoute.get(obs.route).push(obs.total_fare);
}
const medians = {};
for (const [route, fares] of byRoute) {
  fares.sort((a,b) => a-b);
  const mid = Math.floor(fares.length / 2);
  medians[route] = fares.length % 2 ? fares[mid] : (fares[mid - 1] + fares[mid]) / 2;
}
const enriched = observations.map(obs => {
  const median = medians[obs.route];
  const deviationPct = median > 0 ? ((obs.total_fare - median) / median) * 100 : 0;
  const anomaly = Math.abs(deviationPct) >= data.anomaly_threshold_pct;
  const completeness = [obs.route, obs.carrier_code, obs.travel_date, obs.observed_at, obs.total_fare].every(Boolean) ? 1 : 0;
  const score = Math.max(0, Math.min(1, 0.55 * completeness + 0.30 * obs.freshness_score + 0.15 * (anomaly ? 0.25 : 1)));
  return { ...obs, route_median_fare: Number(median.toFixed(2)), deviation_pct: Number(deviationPct.toFixed(2)), anomaly_flag: anomaly, quality_score: Number(score.toFixed(4)) };
});
const anomalies = enriched.filter(o => o.anomaly_flag).length;
return [{ json: { ...data, observations: enriched, anomaly_count: anomalies, anomaly_rate_pct: Number((100 * anomalies / enriched.length).toFixed(2)), distinct_routes: Object.keys(medians).length, quality_avg: Number((enriched.reduce((s,o) => s + o.quality_score, 0) / enriched.length).toFixed(4)) } }];

const data = $input.first().json;
const groups = new Map();
for (const obs of data.observations) {
  const key = `${obs.route}|${obs.lead_time_window}`;
  if (!groups.has(key)) groups.set(key, []);
  groups.get(key).push(obs);
}
const items = [];
for (const [groupKey, observations] of groups) {
  items.push({ json: { ...observations[0], batch_group: groupKey, batch_count: observations.length, observations: observations.map(o => ({ ...o })) } });
}
return items;

const base = $('Run Config + Audit ID').first().json;
const batch = $('Controlled Batch Dispatcher').first().json;
const response = $input.first().json;
const body = { run_id: base.run_id, processed_at: new Date().toISOString(), batch_group: batch.batch_group, batch_count: batch.batch_count, ingest_response: response, source_count: $('Normalize + Hard Validation').first().json.source_count, rejected_count: $('Normalize + Hard Validation').first().json.rejected_count, anomaly_count: $('Anomaly + Quality Scoring').first().json.anomaly_count, anomaly_rate_pct: $('Anomaly + Quality Scoring').first().json.anomaly_rate_pct, quality_avg: $('Anomaly + Quality Scoring').first().json.quality_avg };
return [{ json: body }];

const audit = $('Build Audit Record').first().json;
const indexPayload = $input.first().json;
return [{ json: { ...audit, latest_index: indexPayload.national_index ?? indexPayload.index ?? null, index_status: indexPayload.status ?? 'unavailable', index_payload_present: Object.keys(indexPayload || {}).length > 0, provenance: { workflow_version: $('Run Config + Audit ID').first().json.workflow_version, source_url: $('Run Config + Audit ID').first().json.source_url, generated_at: new Date().toISOString() } } }];
